<?php
namespace App\Http\Controllers;
use App\Models\BillingInfo;
use App\Models\DueCallReminderLog;
use App\Models\MainSiteData;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Str;
class DueCallReminderController extends Controller {
 public function index(){
  $settings=['enabled'=>(bool)MainSiteData::getValue('due_call_enabled',0),'provider'=>(string)MainSiteData::getValue('due_call_provider','protiddhoni'),'api_url'=>(string)MainSiteData::getValue('due_call_api_url','https://portal.protiddhoni-bd.com/api/v1/dynamic-tts/trigger'),'template_id'=>(string)MainSiteData::getValue('due_call_template_id',''),'api_token'=>'','twilio_sid'=>(string)MainSiteData::getValue('due_call_twilio_sid',''),'twilio_auth_token'=>'','twilio_from'=>(string)MainSiteData::getValue('due_call_twilio_from',''),'daily_limit'=>(int)MainSiteData::getValue('due_call_daily_limit',50),'message'=>(string)MainSiteData::getValue('due_call_message','Assalamu Alaikum {customer_name}. Your internet bill due is {due_amount} taka. Please pay at your earliest convenience.'),'payload_json'=>(string)MainSiteData::getValue('due_call_payload_json','{"to":"{phone}","message":"{message}","customer_id":"{customer_id}","amount":"{due_amount}"}')];
  $stats=['today'=>DueCallReminderLog::whereDate('reminder_date',today())->count(),'submitted'=>DueCallReminderLog::whereDate('reminder_date',today())->where('status','submitted')->count(),'failed'=>DueCallReminderLog::whereDate('reminder_date',today())->where('status','failed')->count(),'due'=>BillingInfo::where('due_amount','>',0)->count()];$logs=DueCallReminderLog::latest('id')->paginate(25);return view('xlink.due-call-reminders',compact('settings','stats','logs'));
 }
 public function save(Request $request){$d=$request->validate(['enabled'=>'nullable|boolean','provider'=>'required|in:twilio,custom,protiddhoni','api_url'=>'nullable|url|max:1000','api_token'=>'nullable|string|max:4000','template_id'=>'nullable|string|max:160','twilio_sid'=>'nullable|string|max:64','twilio_auth_token'=>'nullable|string|max:4000','twilio_from'=>'nullable|string|max:32','daily_limit'=>'required|integer|min:1|max:500','message'=>'required|string|min:5|max:1500','payload_json'=>'required|string|max:10000']);if(!is_array(json_decode($d['payload_json'],true)))return back()->withErrors(['payload_json'=>'Payload template must be valid JSON.'])->withInput();if(($d['provider']??'')==='protiddhoni'&&!empty($d['enabled'])&&trim((string)($d['template_id']??''))==='')return back()->withErrors(['template_id'=>'Enter the template ID from your Protiddhoni portal before enabling calls.'])->withInput();if(($d['provider']??'')==='protiddhoni'&&trim((string)($d['api_url']??''))==='')$d['api_url']='https://portal.protiddhoni-bd.com/api/v1/dynamic-tts/trigger';foreach(['api_url','template_id','daily_limit','message','payload_json','provider','twilio_sid','twilio_from'] as $k)MainSiteData::setValue('due_call_'.$k,$d[$k]??'');if(trim((string)($d['api_token']??''))!=='')MainSiteData::setValue('due_call_api_token',Crypt::encryptString($d['api_token']));if(trim((string)($d['twilio_auth_token']??''))!=='')MainSiteData::setValue('due_call_twilio_auth_token',Crypt::encryptString($d['twilio_auth_token']));MainSiteData::setValue('due_call_enabled',!empty($d['enabled'])?'1':'0');Cache::forget('main_site_data_active');return redirect()->route('due-call-reminders.index')->with('call_reminder_message','Settings saved. Keep reminders disabled until provider credentials and a single test call are verified.');}
 public function testConnection(Request $request){$this->assertAdmin($request);$provider=(string)MainSiteData::getValue('due_call_provider','protiddhoni');try{if($provider==='protiddhoni'){$key=$this->secret('due_call_api_token');if($key==='')return back()->with('call_reminder_message','Save the Protiddhoni API key first.');$r=Http::timeout(15)->acceptJson()->withHeaders(['X-API-Key'=>$key])->get('https://portal.protiddhoni-bd.com/api/v1/wallet/balance');if($r->successful())return back()->with('call_reminder_message','Protiddhoni API authentication succeeded. No call was placed.');return back()->with('call_reminder_message','Protiddhoni API check failed (HTTP '.$r->status().'). Verify API key and account access.');}if($provider!=='twilio')return back()->with('call_reminder_message','Connection test is available for Protiddhoni and Twilio. For custom providers, use their documented test endpoint.');$sid=trim((string)MainSiteData::getValue('due_call_twilio_sid',''));$auth=$this->secret('due_call_twilio_auth_token');if(!preg_match('/^AC[0-9a-f]{32}$/i',$sid)||$auth==='')return back()->with('call_reminder_message','Enter and save a valid Twilio Account SID and Auth Token first.');$r=Http::timeout(15)->acceptJson()->withBasicAuth($sid,$auth)->get('https://api.twilio.com/2010-04-01/Accounts/'.$sid.'.json');if($r->successful())return back()->with('call_reminder_message','Twilio connection successful. No phone call was made.');$data=$r->json();$code=is_array($data)?($data['code']??$r->status()):$r->status();return back()->with('call_reminder_message','Twilio connection failed (HTTP '.$r->status().', code '.$code.'). Check SID/Auth Token and account status.');}catch(\Throwable $e){return back()->with('call_reminder_message','Provider connection error: '.Str::limit($e->getMessage(),220));}}
 public function testCall(Request $request){
  $this->assertAdmin($request);$d=$request->validate(['test_phone'=>'required|string|max:24']);$provider=(string)MainSiteData::getValue('due_call_provider','protiddhoni');$to=$this->toE164($d['test_phone']);
  if(!preg_match('/^\+[1-9]\d{7,14}$/',$to))return back()->withErrors(['test_phone'=>'Enter a valid international phone number, e.g. +8801XXXXXXXXX.'])->withInput();
  try{
   if($provider==='protiddhoni'){
    $key=$this->secret('due_call_api_token');$templateId=trim((string)MainSiteData::getValue('due_call_template_id',''));$url=trim((string)MainSiteData::getValue('due_call_api_url','https://portal.protiddhoni-bd.com/api/v1/dynamic-tts/trigger'));
    if($key===''||$templateId===''||!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')return back()->with('call_reminder_message','Save the Protiddhoni API key, template ID and HTTPS call endpoint first.');
    $raw=MainSiteData::getValue('due_call_payload_json','{"to":"{phone}","message":"{message}","customer_id":"{customer_id}","amount":"{due_amount}"}');$payload=is_string($raw)?json_decode($raw,true):$raw;if(!is_array($payload))return back()->withErrors(['payload_json'=>'Provider payload must be valid JSON.'])->withInput();
    $message='This is a test call from X-Link LTD billing reminder.';$mobile=str_starts_with($to,'+880')?'0'.substr($to,4):$to;$body=$this->replacePayload($payload,['{phone}'=>$mobile,'{mobile}'=>$mobile,'{template_id}'=>$templateId,'{message}'=>$message,'{customer_id}'=>'TEST','{customer_name}'=>'Test Customer','{due_amount}'=>'0.00','{company_name}'=>(string)MainSiteData::getValue('site_name','X-Link LTD')]);$body['template_id']=$templateId;$body['mobile']=$mobile;
    $r=Http::timeout(25)->acceptJson()->asJson()->withHeaders(['X-API-Key'=>$key])->post($url,$body);$data=$r->json();if($r->successful())return back()->with('call_reminder_message','Protiddhoni accepted the test request. Check the provider dashboard for final call status; a provider charge may apply.');$detail=is_array($data)?($data['message']??$data['error']??'Provider rejected request'):'Provider rejected request';return back()->with('call_reminder_message','Protiddhoni test request failed (HTTP '.$r->status().'): '.Str::limit((string)$detail,220));
   }
   if($provider!=='twilio')return back()->with('call_reminder_message','Custom provider test calls require its documented request schema and endpoint.');
   $sid=trim((string)MainSiteData::getValue('due_call_twilio_sid',''));$auth=$this->secret('due_call_twilio_auth_token');$from=trim((string)MainSiteData::getValue('due_call_twilio_from',''));if(!preg_match('/^AC[0-9a-f]{32}$/i',$sid)||$auth===''||$from==='')return back()->with('call_reminder_message','Save Twilio SID, Auth Token and a Twilio caller ID first.');
   $twiml='<Response><Say language="en-US">Hello. This is a test call from X Link Billing. Your voice integration is working.</Say></Response>';$r=Http::timeout(25)->acceptJson()->asForm()->withBasicAuth($sid,$auth)->post('https://api.twilio.com/2010-04-01/Accounts/'.$sid.'/Calls.json',['To'=>$to,'From'=>$from,'Twiml'=>$twiml]);$data=$r->json();if($r->successful())return back()->with('call_reminder_message','Twilio accepted the test call request. Check Twilio Call Logs for final status.');$code=is_array($data)?($data['code']??$r->status()):$r->status();$msg=is_array($data)?($data['message']??'Provider rejected request'):'Provider rejected request';return back()->with('call_reminder_message','Test call failed (HTTP '.$r->status().', code '.$code.'): '.Str::limit((string)$msg,220));
  }catch(\Throwable $e){return back()->with('call_reminder_message','Test call request error: '.Str::limit($e->getMessage(),220));}
 }
 private function replacePayload(array $payload,array $vars): array {foreach($payload as $k=>$item)$payload[$k]=is_array($item)?$this->replacePayload($item,$vars):(is_string($item)?strtr($item,$vars):$item);return $payload;}
 public function run(Request $request){$this->assertAdmin($request);Artisan::call('billing:due-call-reminders');return redirect()->route('due-call-reminders.index')->with('call_reminder_message',trim(Artisan::output()));}
 private function assertAdmin(Request $request): void {abort_unless($request->user()&&($request->user()->hasRole('super_admin')||$request->user()->hasRole('admin')),403,'Only administrators can run voice reminder actions.');}
 private function secret(string $key): string {$v=(string)MainSiteData::getValue($key,'');if($v==='')return '';try{return Crypt::decryptString($v);}catch(\Throwable $e){return $v;}}
 private function toE164(string $phone): string {$phone=preg_replace('/[^0-9+]/','',$phone);if(str_starts_with($phone,'01'))return '+880'.substr($phone,1);if(str_starts_with($phone,'880'))return '+'.$phone;return $phone;}
}
